    ? Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds)
    : state.elapsedMs;
  if (selection === state.selection && elapsedMs === state.elapsedMs) return state;
  return withState(state, { selection, elapsedMs });
}

