import { parseBoardCode } from "./boardCode.ts";
import { activateCard, advanceGame, createGame, isWon, MAX_ELAPSED_MS, MAX_MOVES, matchedPairCount } from "./state.ts";

const game = () => createGame("np1-4-1");

