const r=await tools.exec_command({cmd:"node --input-type=module <<'EOF'
import assert from "node:assert/strict";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { chromium } from "@playwright/test";
const browser = await chromium.launch({ headless: true });
try {
  const file = pathToFileURL(resolve("dist/index.html")).href;
  const desktop = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  await desktop.route("http://**", (route) => route.abort());
  await desktop.route("https://**", (route) => route.abort());
  await desktop.goto(file);
  assert.equal(await desktop.locator(".card").count(), 16);
  assert.equal(await desktop.locator(".face-artwork").count(), 0);
  await desktop.screenshot({ path: "/tmp/neon-pairs-desktop.png", fullPage: true });
  await desktop.getByText("Reproduce a game", { exact: true }).click();
  await desktop.getByLabel("Board code").fill("np1-4-1");
  await desktop.getByRole("button", { name: "Load board" }).click();
  await desktop.getByRole("button", { name: "Row 1, column 1, closed" }).click();
  assert.match(await desktop.getByRole("button", { name: /Row 1, column 1,/ }).getAttribute("aria-label"), /cyan solid plus, marker top, revealed/);
  await desktop.getByRole("button", { name: "Row 3, column 4, closed" }).click();
  assert.equal(await desktop.getByText("Pairs: 1/8").count(), 1);
  assert.equal(await desktop.getByText("Moves: 1").count(), 1);
  await desktop.getByRole("button", { name: "Row 1, column 2, closed" }).click();
  await desktop.getByRole("button", { name: "Row 1, column 3, closed" }).click();
  await desktop.waitForTimeout(850);
  assert.equal(await desktop.getByRole("button", { name: "Row 1, column 2, closed" }).count(), 1);
  await desktop.getByRole("button", { name: "Restart" }).click();
  assert.equal(await desktop.getByText("Moves: 0").count(), 1);
  await desktop.getByRole("button", { name: "Row 1, column 1, closed" }).click();
  await desktop.getByRole("button", { name: "Export snapshot" }).click();
  assert.equal(JSON.parse(await desktop.getByLabel("Snapshot JSON").inputValue()).selection.index, 0);
  await desktop.getByRole("button", { name: "Load snapshot" }).click();
  assert.equal(await desktop.locator(".control-status").textContent(), "Loaded snapshot. Select Resume to continue.");
  await desktop.getByRole("button", { name: "Resume" }).click();
  assert.match(await desktop.evaluate(() => document.activeElement?.getAttribute("aria-label") ?? ""), /Row 1, column 1/);

  const mobile = await browser.newPage({ viewport: { width: 360, height: 800 } });
  await mobile.goto(file);
  const mobileLayout = await mobile.evaluate(() => ({ page: document.documentElement.scrollWidth, viewport: innerWidth, card: document.querySelector(".card").getBoundingClientRect().width }));
  assert.ok(mobileLayout.page <= mobileLayout.viewport && mobileLayout.card >= 44);
  await mobile.screenshot({ path: "/tmp/neon-pairs-mobile.png", fullPage: true });

  const large = await browser.newPage({ viewport: { width: 640, height: 400 }, deviceScaleFactor: 2 });
  await large.goto(file);
  await large.getByLabel("Grid size").selectOption("16");
  assert.equal(await large.locator(".card").count(), 256);
  const pageWidth = await large.evaluate(() => ({ page: document.documentElement.scrollWidth, viewport: innerWidth }));
  assert.ok(pageWidth.page <= pageWidth.viewport);
  const last = large.getByRole("button", { name: "Row 16, column 16, closed" });
  assert.ok(await last.evaluate((element) => element.getBoundingClientRect().width >= 44));
  await last.focus();
  const focus = await last.evaluate((element) => {
    const card = element.getBoundingClientRect();
    const board = element.closest(".board-scroll").getBoundingClientRect();
    return { card: [card.left, card.top, card.right, card.bottom], board: [board.left, board.top, board.right, board.bottom], outline: getComputedStyle(element).outlineWidth, offset: getComputedStyle(element).outlineOffset };
  });
  assert.equal(focus.outline, "3px");
  assert.equal(focus.offset, "2px");
  assert.ok(focus.card[0] >= focus.board[0] + 5 && focus.card[2] <= focus.board[2] - 5);
  assert.ok(focus.card[1] >= focus.board[1] + 5 && focus.card[3] <= focus.board[3] - 5);
  await large.screenshot({ path: "/tmp/neon-pairs-zoom.png", fullPage: true });
  console.log(JSON.stringify({ chromium: browser.version(), mobile: mobileLayout, largeBoardCards: 256, focusedLastCard: focus, screenshots: ["/tmp/neon-pairs-desktop.png", "/tmp/neon-pairs-mobile.png", "/tmp/neon-pairs-zoom.png"] }));
} finally {
  await browser.close();
}
EOF",yield_time_ms:1000,max_output_tokens:5000});text(JSON.stringify(r));

