import type { ReactNode } from "react";
import { describeFace, markerCenter } from "./faces.ts";
import type { Shape } from "./faces.ts";

function shapeArtwork(shape: Shape, fill: string, outline: string): ReactNode {
  const strokeWidth = outline === "none" ? 0 : shape === "circle" || shape === "square" ? 5 : 50 / 9;
  switch (shape) {
    case "circle": return <circle cx="50" cy="50" r={outline === "none" ? 25 : 22.5} fill={fill} stroke={outline} strokeWidth={strokeWidth} />;
    case "square": return <rect x={outline === "none" ? 25 : 27.5} y={outline === "none" ? 25 : 27.5} width={outline === "none" ? 50 : 45} height={outline === "none" ? 50 : 45} fill={fill} stroke={outline} strokeWidth={strokeWidth} />;
    case "triangle": return <polygon transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} points="50,25 75,75 25,75" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
    case "diamond": return <polygon transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} points="50,25 75,50 50,75 25,50" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
    case "star": return <polygon transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} points="50,25 56,42 75,42 60,54 66,73 50,61 34,73 40,54 25,42 44,42" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
    case "hexagon": return <polygon transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} points="38,25 62,25 75,50 62,75 38,75 25,50" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
    case "plus": return <path transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} d="M42 25h16v17h17v16H58v17H42V58H25V42h17z" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
    case "chevron": return <path transform={outline === "none" ? undefined : "translate(5 5) scale(0.9)"} d="M25 28 50 50 75 28v18L50 68 25 46z" fill={fill} stroke={outline} strokeWidth={strokeWidth} strokeLinejoin="round" />;
  }
}

export function FaceArtwork({ faceId }: { readonly faceId: number }) {
  const face = describeFace(faceId);
  if (face === null) return null;
  const outline = face.fill === "outline" ? face.color : "none";
  const fill = face.fill === "solid" ? face.color : "none";
  const [cx, cy] = markerCenter(face.marker);
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100" className="face-artwork">
      {shapeArtwork(face.shape, fill, outline)}
      <circle cx={cx} cy={cy} r="5" fill={face.color} stroke="#111625" strokeWidth="3" />
    </svg>
  );
}

export const SHAPES = ["circle", "square", "triangle", "diamond", "star", "hexagon", "plus", "chevron"] as const;
export const MARKERS = ["top", "top-right", "right", "bottom-right", "bottom", "bottom-left", "left", "top-left"] as const;
export const FILLS = ["solid", "outline"] as const;
export const COLORS = ["cyan", "magenta", "green", "yellow", "orange", "violet", "rose", "ice"] as const;
export const PALETTE = ["#63E7FF", "#FF71D6", "#8BEA7D", "#FFE082", "#FFB064", "#B49AFF", "#FF8296", "#D9F3FF"] as const;

export type Shape = (typeof SHAPES)[number];
export type Marker = (typeof MARKERS)[number];
export type Fill = (typeof FILLS)[number];

export interface FaceDescription {
  readonly shape: Shape;
  readonly marker: Marker;
  readonly fill: Fill;
  readonly colorName: string;
  readonly color: string;
  readonly name: string;
}

export function describeFace(id: number): FaceDescription | null {
  if (!Number.isInteger(id) || id < 0 || id >= 128) return null;
  const shape = SHAPES[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = MARKERS[markerIndex];
  const fill = FILLS[Math.floor(id / 64)];
  const colorName = COLORS[markerIndex];
  const color = PALETTE[markerIndex];
  if (shape === undefined || marker === undefined || fill === undefined || colorName === undefined || color === undefined) return null;
  return { shape, marker, fill, colorName, color, name: `${colorName} ${fill} ${shape}, marker ${marker}` };
}

export function markerCenter(marker: Marker): readonly [number, number] {
  switch (marker) {
    case "top": return [50, 10];
    case "top-right": return [78.284, 21.716];
    case "right": return [90, 50];
    case "bottom-right": return [78.284, 78.284];
    case "bottom": return [50, 90];
    case "bottom-left": return [21.716, 78.284];
    case "left": return [10, 50];
    case "top-left": return [21.716, 21.716];
  }
}

import { useRef, useState } from "react";
import { isBoardSize } from "../boardCode.ts";
import type { BoardSize } from "../boardCode.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import { activateCard as applyCard, advanceGame, createGame, isWon } from "../state.ts";
import type { GameState } from "../state.ts";
import { turnAnnouncement } from "./announcements.ts";
import { freshGame, gameForCode } from "./deals.ts";
import { readPreferences, writePreferences } from "./storage.ts";
import type { Preferences } from "./storage.ts";
import { useGameClock } from "./useGameClock.ts";

export interface SessionEvent {
  readonly id: number;
  readonly text: string;
}

interface SessionState {
  readonly game: GameState;
  readonly paused: boolean;
  readonly revision: number;
  readonly celebrationId: number | null;
  readonly preferences: Preferences;
  readonly event: SessionEvent;
  readonly status: string | null;
}

export interface GameSession {
  readonly game: GameState;
  readonly paused: boolean;
  readonly bestMoves: number | null;
  readonly revision: number;
  readonly celebrationId: number | null;
  readonly event: SessionEvent;
  readonly status: string | null;
  readonly activateCard: (index: number) => void;
  readonly startNewGame: () => void;
  readonly restart: () => void;
  readonly changeSize: (size: BoardSize) => void;
  readonly loadBoard: (boardCode: string) => void;
  readonly loadSnapshot: (text: string) => void;
  readonly exportSnapshot: () => string;
  readonly resume: () => void;
}

function initialSession(): SessionState {
  const preferences = readPreferences();
  return {
    game: freshGame(preferences.size), paused: false, revision: 0,
    celebrationId: null, preferences, event: { id: 0, text: "" }, status: null,
  };
}

export function useSession(): GameSession {
  const [session, setSession] = useState(initialSession);
  const stateRef = useRef(session);
  const eventId = useRef(0);
  const refreshClock = useRef<() => void>(() => undefined);
  const invalidateClock = useRef<() => void>(() => undefined);

  const clock = useGameClock(session.game, session.paused, () => stateRef.current, (milliseconds) => {
    const previous = stateRef.current;
    const game = advanceGame(previous.game, milliseconds);
    if (game !== previous.game) {
      const next = { ...previous, game };
      stateRef.current = next;
      setSession(next);
      refreshClock.current();
    }
  });
  refreshClock.current = clock.refresh;
  invalidateClock.current = clock.invalidate;

  const commit = (next: SessionState): void => {
    const previous = stateRef.current;
    const invalidatesTimer = next.game !== previous.game || next.paused !== previous.paused;
    stateRef.current = next;
    setSession(next);
    if (invalidatesTimer) invalidateClock.current();
    else refreshClock.current();
  };

  const makeEvent = (text: string): SessionEvent => {
    eventId.current += 1;
    return { id: eventId.current, text };
  };

  const syncClock = clock.sync;

  const activateCard = (index: number): void => {
    syncClock();
    const previous = stateRef.current;
    if (previous.paused) return;
    const game = applyCard(previous.game, index);
    if (game === previous.game) return;

    const text = turnAnnouncement(previous.game, game);
    const winningTurn = !isWon(previous.game) && isWon(game);
    let preferences = previous.preferences;
    if (winningTurn) {
      const oldBest = preferences.bestMoves[game.board.size];
      if (oldBest === undefined || game.moves < oldBest) {
        preferences = {
          size: game.board.size,
          bestMoves: Object.freeze({ ...preferences.bestMoves, [game.board.size]: game.moves }),
        };
        writePreferences(preferences);
      }
    }
    commit({
      ...previous, game, preferences,
      celebrationId: winningTurn ? eventId.current + 1 : previous.celebrationId,
      event: text === null ? previous.event : makeEvent(text),
    });
  };

  const startGame = (game: GameState, preferences = stateRef.current.preferences): void => {
    const previous = stateRef.current;
    commit({ ...previous, game, preferences, paused: false, revision: previous.revision + 1,
      celebrationId: null, status: null });
  };

  const startNewGame = (): void => {
    syncClock();
    const game = stateRef.current.game;
    startGame(freshGame(game.board.size, game.board.seed));
  };

  const restart = (): void => {
    syncClock();
    startGame(gameForCode(stateRef.current.game.board.code));
  };

  const changeSize = (size: BoardSize): void => {
    syncClock();
    const previous = stateRef.current;
    if (!isBoardSize(size) || size === previous.game.board.size) return;
    const preferences: Preferences = { ...previous.preferences, size };
    writePreferences(preferences);
    startGame(freshGame(size), preferences);
  };

  const loadBoard = (boardCode: string): void => {
    syncClock();
    const previous = stateRef.current;
    const game = createGame(boardCode.trim());
    if (game === null) {
      const status = "Invalid board code.";
      commit({ ...previous, status, event: makeEvent(status) });
      return;
    }
    const preferences: Preferences = { ...previous.preferences, size: game.board.size };
    writePreferences(preferences);
    startGame(game, preferences);
  };

  const loadSnapshot = (text: string): void => {
    syncClock();
    const previous = stateRef.current;
    const game = decodeSnapshot(text);
    if (game === null) {
      const status = "Invalid snapshot.";
      commit({ ...previous, status, event: makeEvent(status) });
      return;
    }
    const completed = isWon(game);
    const status = completed ? "Loaded completed snapshot." : "Loaded snapshot. Select Resume to continue.";
    const preferences: Preferences = { ...previous.preferences, size: game.board.size };
    writePreferences(preferences);
    commit({ ...previous, game, preferences, paused: !completed,
      revision: previous.revision + 1, celebrationId: null, status, event: makeEvent(status) });
  };

  const exportSnapshot = (): string => {
    const current = stateRef.current;
    return encodeSnapshot(clock.gameAtNow(current.game));
  };

  const resume = (): void => {
    syncClock();
    const previous = stateRef.current;
    if (!previous.paused || isWon(previous.game)) return;
    commit({ ...previous, paused: false, status: null });
  };

  return {
    game: session.game, paused: session.paused,
    bestMoves: session.preferences.bestMoves[session.game.board.size] ?? null,
    revision: session.revision, celebrationId: session.celebrationId,
    event: session.event, status: session.status,
    activateCard, startNewGame, restart, changeSize, loadBoard, loadSnapshot, exportSnapshot, resume,
  };
}

import { BOARD_SIZES, isBoardSize } from "../boardCode.ts";
import type { BoardSize } from "../boardCode.ts";
import { MAX_MOVES } from "../state.ts";

export const PREFERENCES_KEY = "neon-pairs.preferences.v1";

export interface Preferences {
  readonly size: BoardSize;
  readonly bestMoves: Readonly<Partial<Record<BoardSize, number>>>;
}

export interface StoragePort {
  getItem(key: string): string | null;
  setItem(key: string, value: string): void;
}

const DEFAULT_PREFERENCES: Preferences = Object.freeze({ size: 4, bestMoves: Object.freeze({}) });

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isBestScore(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 && value <= MAX_MOVES;
}

function browserStorage(): StoragePort {
  return window.localStorage;
}

export function readPreferences(
  storageFactory: () => StoragePort = browserStorage,
): Preferences {
  try {
    const text = storageFactory().getItem(PREFERENCES_KEY);
    if (text === null) return DEFAULT_PREFERENCES;
    const value: unknown = JSON.parse(text);
    if (!isRecord(value) || value.version !== 1) return DEFAULT_PREFERENCES;

    const size = isBoardSize(value.size) ? value.size : DEFAULT_PREFERENCES.size;
    const bestMoves: Partial<Record<BoardSize, number>> = {};
    if (isRecord(value.bestMoves)) {
      for (const boardSize of BOARD_SIZES) {
        const score = value.bestMoves[boardSize];
        if (isBestScore(score)) bestMoves[boardSize] = score;
      }
    }
    return { size, bestMoves: Object.freeze(bestMoves) };
  } catch {
    return DEFAULT_PREFERENCES;
  }
}

export function writePreferences(
  preferences: Preferences,
  storageFactory: () => StoragePort = browserStorage,
): void {
  try {
    storageFactory().setItem(PREFERENCES_KEY, JSON.stringify({
      version: 1,
      size: preferences.size,
      bestMoves: preferences.bestMoves,
    }));
  } catch {
    // Storage is optional; the current game remains usable in memory.
  }
}

import { describe, expect, it } from "vitest";
import { replayGame, MAX_REPLAY_ACTIONS, MAX_REPLAY_BYTES } from "./replay.ts";

function replay(actions: readonly { atMs: number; index: number }[], endMs: number): string {
  return JSON.stringify({ version: 1, boardCode: "np1-4-1", actions, endMs });
}

describe("replayGame", () => {
  it("matches the documented replay vector", () => {
    const state = replayGame(replay([{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], 800));
    expect(state).not.toBeNull();
    expect(state).toMatchObject({ matched: [0, 11], moves: 1, elapsedMs: 800 });
  });

  it("does not charge time before the first reveal and freezes on completion", () => {
    const beforeReveal = replayGame(replay([{ atMs: 5_000, index: 0 }], 8_000));
    expect(beforeReveal?.elapsedMs).toBe(3_000);
    const pairs = [[2, 6], [10, 14], [4, 5], [8, 15], [12, 13], [3, 7], [0, 11], [1, 9]] as const;
    const actions = pairs.flatMap((pair, pairIndex) => pair.map((index) => ({ atMs: pairIndex === 7 ? 1_000 : 0, index })));
    const done = replayGame(replay(actions, 3_000));
    expect(done?.elapsedMs).toBe(1_000);
  });

  it("closes a mismatch before an action at its exact deadline", () => {
    const state = replayGame(replay([
      { atMs: 0, index: 0 }, { atMs: 0, index: 1 }, { atMs: 800, index: 2 },
    ], 800));
    expect(state).toMatchObject({ moves: 1, elapsedMs: 800, selection: { kind: "one", index: 2 } });
  });

  it.each([
    { version: 2, boardCode: "np1-4-1", actions: [], endMs: 0 },
    { version: 1, boardCode: "np1-04-1", actions: [], endMs: 0 },
    { version: 1, boardCode: "np1-4-1", actions: [{ atMs: 1, index: 0, extra: 1 }], endMs: 1 },
    { version: 1, boardCode: "np1-4-1", actions: [{ atMs: 0, index: 16 }], endMs: 0 },
    { version: 1, boardCode: "np1-4-1", actions: [{ atMs: 2, index: 0 }, { atMs: 1, index: 1 }], endMs: 2 },
    { version: 1, boardCode: "np1-4-1", actions: [{ atMs: 2, index: 0 }], endMs: 1 },
    { version: 1, boardCode: "np1-4-1", actions: [], endMs: -1 },
    { version: 1, boardCode: "np1-4-1", actions: [], endMs: 0, extra: true },
  ])("rejects invalid replay records", (value) => {
    expect(replayGame(JSON.stringify(value))).toBeNull();
  });

  it("rejects malformed, oversized and overlong replay input", () => {
    expect(replayGame("{" )).toBeNull();
    expect(replayGame(" ".repeat(MAX_REPLAY_BYTES + 1))).toBeNull();
    expect(replayGame(replay(Array.from({ length: MAX_REPLAY_ACTIONS + 1 }, () => ({ atMs: 0, index: 0 })), 0))).toBeNull();
  });
});

import { useEffect, useRef, useState } from "react";
import { advanceGame, isWon, MAX_ELAPSED_MS } from "../state.ts";
import type { GameState } from "../state.ts";

interface ClockSession {
  readonly game: GameState;
  readonly paused: boolean;
}

function canRun(session: ClockSession): boolean {
  return session.game.started && !session.paused && !isWon(session.game) && !document.hidden;
}

export function useGameClock(
  game: GameState,
  paused: boolean,
  readSession: () => ClockSession,
  advance: (milliseconds: number) => void,
) {
  const sample = useRef<number | null>(null);
  const active = useRef(false);
  const generation = useRef(0);
  const readLatest = useRef(readSession);
  const advanceLatest = useRef(advance);
  const [visibilityRevision, setVisibilityRevision] = useState(0);
  readLatest.current = readSession;
  advanceLatest.current = advance;

  const refresh = (): void => {
    active.current = canRun(readLatest.current());
  };

  const invalidate = (): void => {
    generation.current += 1;
    refresh();
  };

  const sync = (): void => {
    const now = performance.now();
    const delta = sample.current === null ? 0 : Math.max(0, now - sample.current);
    sample.current = now;
    const wasActive = active.current;
    refresh();
    if (wasActive && delta > 0) advanceLatest.current(delta);
  };

  const gameAtNow = (current: GameState): GameState => {
    if (!active.current || sample.current === null) return current;
    const delta = Math.max(0, performance.now() - sample.current);
    return advanceGame(current, delta);
  };

  useEffect(() => {
    sample.current = performance.now();
    refresh();
    const onVisibilityChange = (): void => {
      sync();
      setVisibilityRevision((revision) => revision + 1);
    };
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => document.removeEventListener("visibilitychange", onVisibilityChange);
  }, []);

  useEffect(() => {
    if (paused || document.hidden || !game.started || isWon(game)) return;
    if (game.elapsedMs >= MAX_ELAPSED_MS && game.selection.kind !== "mismatch") return;
    const nextSecond = game.elapsedMs >= MAX_ELAPSED_MS
      ? Infinity : 1000 - (game.elapsedMs % 1000);
    const mismatchEnd = game.selection.kind === "mismatch" ? game.selection.remainingMs : Infinity;
    const delay = Math.max(1, Math.ceil(Math.min(nextSecond, mismatchEnd)));
    let current = true;
    const currentGeneration = generation.current;
    const timeout = window.setTimeout(() => {
      if (current && currentGeneration === generation.current) sync();
    }, delay);
    return () => {
      current = false;
      generation.current += 1;
      window.clearTimeout(timeout);
    };
  }, [game, paused, visibilityRevision]);

  return { sync, refresh, invalidate, gameAtNow };
}

import { describe, expect, it } from "vitest";
import { decodeSnapshot, encodeSnapshot, MAX_SNAPSHOT_BYTES } from "./snapshot.ts";
import { activateCard, createGame } from "./state.ts";

const base = {
  version: 1,
  boardCode: "np1-4-1",
  matched: [],
  selection: { kind: "closed" },
  moves: 0,
  elapsedMs: 0,
  started: false,
};

function text(value: unknown): string {
  return JSON.stringify(value);
}

function finishDeal() {
  const initial = createGame("np1-4-1");
  if (initial === null) throw new Error("known board code rejected");
  let state = initial;
  const firstByFace = new Map<number, number>();
  initial.deck.forEach((face, index) => {
    const first = firstByFace.get(face);
    if (first === undefined) firstByFace.set(face, index);
    else state = activateCard(activateCard(state, first), index);
  });
  return state;
}

describe("snapshot format", () => {
  it("round trips new, started, mismatch and completed positions", () => {
    const initial = createGame("np1-4-1");
    expect(initial).not.toBeNull();
    if (initial === null) return;
    const states = [initial, activateCard(initial, 0), activateCard(activateCard(initial, 0), 1), finishDeal()];
    for (const state of states) expect(decodeSnapshot(encodeSnapshot(state))).toEqual(state);
  });

  it("rounds a fractional pending timer up to at least one whole millisecond", () => {
    const initial = createGame("np1-4-1");
    expect(initial).not.toBeNull();
    if (initial === null) return;
    const mismatch = activateCard(activateCard(initial, 0), 1);
    const fractional = { ...mismatch, selection: { kind: "mismatch" as const, first: 0, second: 1, remainingMs: 0.2 } };
    const restored = decodeSnapshot(encodeSnapshot(fractional));
    expect(restored?.selection).toMatchObject({ kind: "mismatch", remainingMs: 1 });
  });

  it.each([
    { ...base, extra: true },
    { ...base, version: 2 },
    { ...base, boardCode: " np1-4-1" },
    { ...base, moves: -1 },
    { ...base, moves: 1_000_000 },
    { ...base, elapsedMs: 359_999_360 },
    { ...base, started: true },
    { ...base, matched: [0] },
    { ...base, started: true, selection: { kind: "one", index: 16 } },
    { ...base, selection: { kind: "closed", extra: 1 } },
    { ...base, started: true, moves: 1, selection: { kind: "mismatch", first: 0, second: 11, remainingMs: 800 } },
    { ...base, started: true, moves: 1, selection: { kind: "mismatch", first: 0, second: 1, remainingMs: 0 } },
  ])("rejects inconsistent or unknown snapshot data", (value) => {
    expect(decodeSnapshot(text(value))).toBeNull();
  });

  it("rejects malformed and oversized UTF-8 input", () => {
    expect(decodeSnapshot("{" )).toBeNull();
    expect(decodeSnapshot(" ".repeat(MAX_SNAPSHOT_BYTES + 1))).toBeNull();
  });
});

import { open } from "node:fs/promises";
import { encodeSnapshot } from "../game/snapshot.ts";
import { MAX_REPLAY_BYTES, replayGame } from "../game/replay.ts";

async function readBoundedText(path: string): Promise<string | null> {
  const handle = await open(path, "r");
  try {
    const bytes = new Uint8Array(MAX_REPLAY_BYTES + 1);
    const result = await handle.read(bytes, 0, bytes.length, 0);
    if (result.bytesRead > MAX_REPLAY_BYTES) return null;
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes.subarray(0, result.bytesRead));
  } finally {
    await handle.close();
  }
}

async function main(): Promise<number> {
  const paths = process.argv.slice(2);
  if (paths.length !== 1) {
    process.stderr.write("Usage: npm run --silent replay -- PATH\n");
    return 2;
  }
  try {
    const text = await readBoundedText(paths[0] ?? "");
    if (text === null) {
      process.stderr.write("Invalid replay file.\n");
      return 1;
    }
    const state = replayGame(text);
    if (state === null) {
      process.stderr.write("Invalid replay file.\n");
      return 1;
    }
    process.stdout.write(`${encodeSnapshot(state)}\n`);
    return 0;
  } catch {
    process.stderr.write("Unable to read replay file.\n");
    return 1;
  }
}

const exitCode = await main();
if (exitCode !== 0) process.exitCode = exitCode;

