import { expect, test } from "@playwright/test";
import { activateCards, boardCards, loadBoardCode, loadSnapshot, openGame, saveEvidence } from "./support.ts";
import { referenceDeck, referencePairs } from "./reference-deck.ts";

async function minimumCardWidth(page: import("@playwright/test").Page): Promise<number> {
  return page.locator(".card").evaluateAll((cards) => Math.min(...cards.map((card) => card.getBoundingClientRect().width)));
}

async function fullFocusRingVisible(page: import("@playwright/test").Page, index: number): Promise<boolean> {
  return boardCards(page).nth(index).evaluate((card) => {
    const board = card.closest(".board-scroll");
    if (!(board instanceof HTMLElement)) return false;
    const cardBox = card.getBoundingClientRect();
    const boardBox = board.getBoundingClientRect();
    return cardBox.left - 5 >= boardBox.left && cardBox.top - 5 >= boardBox.top
      && cardBox.right + 5 <= boardBox.right && cardBox.bottom + 5 <= boardBox.bottom;
  });
}

test("captures desktop, phone, and zoom layouts with reachable 16x16 cards", async ({ browser, page }) => {
